"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["30368"],{75512(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_do_recurso_da_etapa.prazo_em_dias_corridos","status":422,"titulo":"O prazo do recurso n\xe3o aceita dias corridos"},"descricao":{"codigo":"uniplus.selecao.configuracao_do_recurso_da_etapa.prazo_em_dias_corridos","requisitos":["UNI-REQ-0113"],"oQueAconteceu":["O prazo declarado pela configura\xe7\xe3o do recurso de uma etapa est\xe1 em **dias corridos**. Isso vale para os dois prazos da configura\xe7\xe3o: o de **interposi\xe7\xe3o**, na 1\xaa inst\xe2ncia, e o da **2\xaa inst\xe2ncia**. A recusa sai com **422**, nada \xe9 gravado, e o campo recusado \xe9 `etapas[i].recursos[j].prazoUnidade` (interposi\xe7\xe3o) ou `etapas[i].recursos[j].prazoSegundaInstanciaUnidade` (2\xaa inst\xe2ncia), em que `i` \xe9 a posi\xe7\xe3o da etapa e `j`, a do recurso na etapa.","A mensagem da resposta diz qual dos prazos foi recusado: \\"O prazo de interposi\xe7\xe3o deve ser informado em dias \xfateis ou em horas; dias corridos n\xe3o s\xe3o aceitos.\\" ou a mesma frase com \\"prazo da 2\xaa inst\xe2ncia\\".","O prazo do recurso corre s\xf3 em dia \xfatil. \xc9 o prazo em que o candidato pode recorrer, e o tempo em que ele n\xe3o tem como agir n\xe3o pode consumi-lo. Declarar dia corrido faria o prazo encolher sempre que ca\xedsse em feriado ou fim de semana (UNI-REQ-0113)."],"comoResolver":["Reescreva o prazo na unidade que o edital usa: dias \xfateis (`DIAS_UTEIS`), em valor inteiro, ou horas (`HORAS`). Se o edital diz \\"dois dias \xfateis\\", declare dois dias \xfateis, sem aproximar para dias corridos. Se o prazo \xe9 menor que um dia, declare-o em horas: fra\xe7\xe3o de dia \xfatil tamb\xe9m \xe9 recusada, com [causa pr\xf3pria](/erros/uniplus.selecao.configuracao_do_recurso_da_etapa.prazo_em_fracao_de_dia_util)."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo","Leitura do documento de configura\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao do recurso da etapa"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);